        except HarnessMessageError:
            raise
        except (OSError, TimeoutError) as e:
            last_exc = e
            if log_sink is not None:
                log_sink.write_control(
                    "conductor.run_failed",
                    reason="exception",
                    detail=repr(e),
                    attempt=attempt + 1,
